settings:
{
  "$schema": "https://raw.githubusercontent.com/mbcrawfo/SqlSource/main/schemas/settings-v1.schema.json",
  // The output of every .sql file of this folder: methods, so that each query gets an extension method on a connection
  // and its models.
  "output": "methods",
}
{
  "$schema": "https://raw.githubusercontent.com/mbcrawfo/SqlSource/main/schemas/settings-v1.schema.json",
  // No settings file above this folder applies to the project.
  "root": true,
  // The dialect of every query of the project.
  "dialect": "postgres",
  "typeOverrides": {
    // Every timestamptz is a DateTimeOffset, which Dapper reads through UtcDateTimeOffsetHandler.
    "timestamptz": "System.DateTimeOffset",
  },
  "columnTypes": {
    // order_lines.order_id is an OrderId, by its short name, in every query that reads it.
    "order_lines.order_id": "OrderId",
  },
}
